package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Collection;
import java.util.Map;
import java.util.stream.Collectors;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.stereotype.Component;

/**
 * Computes and stamps each owner's household size — the number of owners sharing its
 * {@code householdId} (see {@link AssignHousehold}), counting the owner itself.
 *
 * <p>The size depends on <em>other</em> owners, so it cannot be derived from a single {@link Owner}
 * inside the mapper. This component owns that repository lookup and writes the result onto the
 * (transient) {@link Owner#getHouseholdSize()} before the owner is mapped, so {@code OwnerMapper}
 * stays a pure transformation. An owner with no {@code householdId} is a single-member household.
 */
@Component
public class OwnerHousehold {

    private final OwnerRepository ownerRepository;

    public OwnerHousehold(OwnerRepository ownerRepository) {
        this.ownerRepository = ownerRepository;
    }

    /** Stamp a single owner's household size, computed against all current owners. */
    public Owner stamp(Owner owner) {
        if (owner != null) {
            owner.setHouseholdSize(sizeIn(owner, householdCounts()));
        }
        return owner;
    }

    /** Stamp every owner in the collection, reading all owners once for the whole batch. */
    public <C extends Collection<Owner>> C stampAll(C owners) {
        if (owners != null && !owners.isEmpty()) {
            Map<String, Long> counts = householdCounts();
            owners.forEach(owner -> owner.setHouseholdSize(sizeIn(owner, counts)));
        }
        return owners;
    }

    /** Number of existing owners grouped by household id. */
    private Map<String, Long> householdCounts() {
        return ownerRepository.findAll().stream()
                .filter(existing -> existing.getHouseholdId() != null)
                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
    }

    /** The owner's household size from pre-computed counts, always at least 1 (the owner itself). */
    private int sizeIn(Owner owner, Map<String, Long> counts) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return 1;
        }
        return (int) Math.max(counts.getOrDefault(householdId, 0L), 1L);
    }
}
===== HouseholdKey =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.function.common.Hashes;

/**
 * The single definition of an owner's {@code householdId}: a deterministic identifier derived from
 * the owner's last name and postcode, so owners with the same last name and postcode share it
 * automatically. The value is the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode}, where the last name is compared case-insensitively
 * after collapsing runs of whitespace.
 *
 * <p>Because it is a pure function of {@code (lastName, postcode)}, every owner computes its own id
 * independently and members of one household always agree — there is nothing to link or backfill.
 * Shared by {@link AssignHousehold} (which stamps it onto the new owner), {@link RequireUniqueIdentity}
 * (duplicate detection) and {@link AssignOwnerPossibleDuplicate} (soft-match), so every place that
 * keys off the household applies the one rule and they cannot drift apart.
 *
 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
 * expose exactly one public method.
 */
final class HouseholdKey {

    /** Length of the household id: the first 12 hex characters of the SHA-256 digest. */
    private static final int ID_LENGTH = 12;

    private HouseholdKey() {
    }

    /**
     * The deterministic {@code householdId} for the given last name and postcode: the first 12 hex
     * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. A {@code null} postcode
     * is treated as the empty string.
     */
    static String householdId(String lastName, String postcode) {
        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        return Hashes.sha256Hex(key).substring(0, ID_LENGTH);
    }

    /**
     * The deterministic {@code householdId} of the given owner — the single home of "which two fields
     * make a household", mirroring {@link IdentityKey#ofOwner}, so callers never re-pluck the tuple.
     */
    static String householdId(Owner owner) {
        return householdId(owner.getLastName(), owner.getPostcode());
    }

    /** Lower-cases and collapses runs of whitespace to a single space for case- and
     *  whitespace-insensitive comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== RequirePostcodeForCity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.PostcodeOutOfRangeException;
import org.springframework.samples.petclinic.rest.function.common.Localities;

/**
 * Validates the owner's optional {@code postcode} against the owner's city region. Postcode is checked
 * ONLY WHEN PRESENT: an owner with no postcode passes through untouched, keeping the request contract
 * backward-compatible. Its 4-digit shape is enforced earlier by bean validation ({@code @Pattern} on
 * the DTO, a 400 via {@code ValidationExceptionHandler}); this step adds the region range check.
 *
 * <p>The region is derived from the city via the fixed {@link Localities} table (NSW 2000-2099,
 * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. A supplied
 * postcode outside its region's range is rejected with a 400 by {@code PostcodeOutOfRangeExceptionHandler}.
 */
public class RequirePostcodeForCity {

    public void service(@Val OwnerFieldsDto owner) throws PostcodeOutOfRangeException {
        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return;
        }
        int[] range = Localities.postcodeRange(owner.getCity());
        if (range == null) {
            return; // city has no known region: any 4-digit postcode is accepted
        }
        int value;
        try {
            value = Integer.parseInt(postcode);
        }
        catch (NumberFormatException ex) {
            throw new PostcodeOutOfRangeException(postcode, owner.getCity());
        }
        if (value < range[0] || value > range[1]) {
            throw new PostcodeOutOfRangeException(postcode, owner.getCity());
        }
    }
}
===== RequireCityCapacity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a create-owner request with a 409 (via {@code CityAtCapacityExceptionHandler}) when the
 * owner's city already contains {@code CAPACITY} (50) or more owners, compared case-insensitively.
 * The new owner is not persisted yet, so every match found is an existing owner.
 */
public class RequireCityCapacity {

    private static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = owner.getCity();
        if (city == null) {
            return;
        }
        long count = ownerRepository.findAll().stream()
                .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
                .count();
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city);
        }
    }
}
===== RequireOwnerFields =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;

/**
 * Runs after {@link ValidateOwner} in the create-owner pipeline and enforces the one rule the DTO's
 * declarative constraints cannot express: no required field may be <em>blank</em>. {@code address} and
 * {@code city} carry only {@code @Size(min = 1)} (no pattern), so a whitespace-only value passes schema
 * validation; this step rejects it with a 400 listing every offending field.
 *
 * <p>Layered on top of {@code @Valid} rather than replacing it: null/empty/pattern violations are still
 * caught upstream by {@link ValidateOwner} (consistent with {@code PUT /owners/{ownerId}}), and both
 * paths surface the offending field names in the response {@code errors} array.
 */
public class RequireOwnerFields {

    public void service(@Val OwnerFieldsDto owner) throws MissingOwnerFieldsException {
        List<String> missing = new ArrayList<>();
        if (isBlank(owner.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(owner.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(owner.getAddress())) {
            missing.add("address");
        }
        if (isBlank(owner.getCity())) {
            missing.add("city");
        }
        if (isBlank(owner.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
